import {
  AlipayCircleOutlined,
  TaobaoCircleOutlined,
  WeiboCircleOutlined,
} from '@ant-design/icons';
import { SelectLang } from '@umijs/max';
import { Alert } from 'antd';
import { createStyles } from 'antd-style';

export const useStyles = createStyles(({ token }) => {
  return {
    action: {
      marginLeft: '8px',
      color: 'rgba(0, 0, 0, 0.2)',
      fontSize: '24px',
      verticalAlign: 'middle',
      cursor: 'pointer',
      transition: 'color 0.3s',
      '&:hover': {
        color: token.colorPrimaryActive,
      },
    },
    lang: {
      width: 42,
      height: 42,
      lineHeight: '42px',
      position: 'fixed',
      right: 16,
      borderRadius: token.borderRadius,
      ':hover': {
        backgroundColor: token.colorBgTextHover,
      },
    },
    container: {
      display: 'flex',
      flexDirection: 'column',
      height: '100vh',
      overflow: 'auto',
      backgroundImage:
        "url('https://mdn.alipayobjects.com/yuyan_qk0oxh/afts/img/V-_oS6r-i7wAAAAAAAAAAAAAFl94AQBr')",
      backgroundSize: '100% 100%',
    },
  };
});

const ALIPAY_AUTHORIZE_URL =
  "https://openauth.alipay.com/oauth2/publicAppAuthorize.htm";
// 沙箱的话用：openauth-sandbox.dl.alipaydev.com


export const ActionIcons = () => {
  const { styles } = useStyles();

  function goAlipayLogin() {
    const appId = process.env.REACT_APP_ALIPAY_APP_ID! || '2021006116650457';
    const redirectUri =
      process.env.REACT_APP_ALIPAY_REDIRECT_URI ||
      "https://bff-next-main.vercel.app/main/auth/alipay/callback";

    console.log('appId', appId, redirectUri);
    // debugger
    const url =
      `${ALIPAY_AUTHORIZE_URL}` +
      `?app_id=${appId}` +
      `&scope=auth_user` + // 需要用户授权信息
      `&redirect_uri=${encodeURIComponent(redirectUri)}`;

    window.location.href = url;
  }

  return (
    <>
      <AlipayCircleOutlined
        key="AlipayCircleOutlined"
        className={styles.action}
        onClick={goAlipayLogin}
      />
      <TaobaoCircleOutlined
        key="TaobaoCircleOutlined"
        className={styles.action}
      />
      <WeiboCircleOutlined
        key="WeiboCircleOutlined"
        className={styles.action}
      />
    </>
  );
};

export const Lang = () => {
  const { styles } = useStyles();

  return (
    <div className={styles.lang} data-lang>
      {SelectLang && <SelectLang />}
    </div>
  );
};

export const LoginMessage: React.FC<{
  content: string;
}> = ({ content }) => {
  return (
    <Alert
      style={{
        marginBottom: 24,
      }}
      message={content}
      type="error"
      showIcon
    />
  );
};
