import authApi from "./authApi"
import { smsCodeProps } from "./type"

// 登录接口
export const login = async (values: API.LoginParams) => {
    let res = authApi.post('/login', values)
    return res
}

// 获取图形码
export const getCaptcha = async () => {
    let res = authApi.get('/captcha/graph')
    return res
}

// 获取图形码 算术表达式
export const getCaptchaMath = async () => {
    let res = authApi.get('/captcha/math')
    return res
}

// 获取图形码 trek
export const getCaptchaTrek = async () => {
    let res = authApi.get('/captcha/trek')
    return res
}


// 获取手机验证码
export const getSms = async (values: { phone: string }) => {
    let res = authApi.post('/sms/send', values)
    return res
}

// 校验验证码
export const checkSmsCode = async (values: smsCodeProps) => {
    let res = authApi.post('/sms/verify', values)
    return res
}
